use super :: operation :: PermissionOperation ; use super :: policy :: Policy ; use crate :: PolicyConfig ; use crate :: policies :: Permission ; use pretty_assertions :: assert_eq ; use super :: * ; use crate :: { ExecuteRule , Fetch , Permission , Policy , PolicyConfig , ReadRule , Rule , WriteRule } ; impl < 'a > PolicyEngine < 'a > { # [doc = " Create a new PolicyEngine from a workflow"] pub fn new (policies : & 'a PolicyConfig) -> Self { Self { policies } } # [doc = " Check if an operation is allowed"] # [doc = " Returns permission result"] pub fn can_perform (& self , operation : & PermissionOperation) -> Permission { self . evaluate_policies (operation) } # [doc = " Internal helper function to evaluate policies for a given operation"] # [doc = " Returns permission result, defaults to Confirm if no policies match"] fn evaluate_policies (& self , operation : & PermissionOperation) -> Permission { let has_policies = ! self . policies . policies . is_empty () ; if ! has_policies { return Permission :: Confirm ; } let mut last_allow : Option < Permission > = None ; if let Some (permission) = self . evaluate_policy_set (self . policies . policies . iter () , operation) { match permission { Permission :: Deny | Permission :: Confirm => { return permission ; } Permission :: Allow => { last_allow = Some (permission) ; } } } last_allow . unwrap_or (Permission :: Confirm) } # [doc = " Helper function to evaluate a set of policies"] # [doc = " Returns the first non-Allow result, or the last Allow result if all are"] # [doc = " Allow"] fn evaluate_policy_set < 'p , I : IntoIterator < Item = & 'p Policy > > (& self , policies : I , operation : & PermissionOperation ,) -> Option < Permission > { let mut last_allow : Option < Permission > = None ; for policy in policies { if let Some (permission) = policy . eval (operation) { match permission { Permission :: Deny | Permission :: Confirm => { return Some (permission) ; } Permission :: Allow => { last_allow = Some (permission) ; } } } } last_allow } }